using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using UnityEngine;

namespace Cyberpunk.Audio
{
    /// <summary>
    /// Spoken voice for dialogue boxes. Every line shown by the dialogue HUDs is looked up by a hash of its
    /// text and, when a clip exists in Resources/VoiceLines, played through one shared 2D source.
    ///
    /// The clips are generated by Tools/VoiceGen (extract_dialogue.py + generate_voices.py), which use the
    /// same normalisation as <see cref="Key"/>: tags, speaker prefix, quotes, case and punctuation do not matter.
    /// In the editor, lines without a clip are appended to VoiceLines/missing.tsv so the generator can add them.
    /// </summary>
    public static class DialogueVoice
    {
        public const string ResourceFolder = "VoiceLines/";

        public static bool Enabled = true;
        public static float Volume = 1f;

        private static readonly Dictionary<string, AudioClip> Cache = new Dictionary<string, AudioClip>();
        private static readonly HashSet<string> Reported = new HashSet<string>();
        private static readonly Regex Tags = new Regex("<[^>]+>", RegexOptions.Compiled);
        private static readonly Regex NonAlnum = new Regex("[^a-z0-9]", RegexOptions.Compiled);

        private static AudioSource _source;
        private static float _suppressUntil;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics()
        {
            Cache.Clear();
            Reported.Clear();
            _source = null;
            _suppressUntil = 0f;
        }

        // ── Key (must match Tools/VoiceGen/voice_common.py) ─────────────────────

        public static string Key(string text)
        {
            string norm = Normalize(text);
            if (norm.Length == 0) return "";
            using (var sha = SHA1.Create())
            {
                byte[] h = sha.ComputeHash(Encoding.UTF8.GetBytes(norm));
                var sb = new StringBuilder(16);
                for (int i = 0; i < 8; i++) sb.Append(h[i].ToString("x2"));
                return sb.ToString();
            }
        }

        private static string Normalize(string text)
        {
            if (string.IsNullOrEmpty(text)) return "";
            text = Tags.Replace(text, "");
            text = text.Trim();

            int idx = text.IndexOf(':');
            if (idx > 0 && idx < 35)
            {
                string cand = text.Substring(0, idx).Trim();
                if (!cand.Contains("<") && !cand.Contains("\n") && !cand.Contains("http"))
                    text = text.Substring(idx + 1).Trim();
            }

            if (text.Length >= 2 && text[0] == '"' && text[text.Length - 1] == '"')
                text = text.Substring(1, text.Length - 2);

            return NonAlnum.Replace(text.ToLowerInvariant(), "");
        }

        // ── Lookup / playback ───────────────────────────────────────────────────

        public static AudioClip Find(string speaker, string text)
        {
            string key = Key(text);
            if (key.Length == 0) return null;

            if (Cache.TryGetValue(key, out var cached)) return cached;

            var clip = Resources.Load<AudioClip>(ResourceFolder + key);
            Cache[key] = clip;
            if (clip == null) ReportMissing(speaker, text, key);
            return clip;
        }

        /// <summary>Starts the voice line for this text (stopping any previous one). Returns the clip, or null.</summary>
        public static AudioClip Play(string speaker, string text)
        {
            Stop();
            if (!Enabled || Time.unscaledTime < _suppressUntil) return null;

            var clip = Find(speaker, text);
            if (clip == null) return null;

            EnsureSource();
            _source.clip = clip;
            _source.volume = Mathf.Clamp01(Volume);
            _source.Play();
            return clip;
        }

        public static void Stop()
        {
            if (_source != null && _source.isPlaying) _source.Stop();
        }

        public static bool IsPlaying => _source != null && _source.isPlaying;

        /// <summary>Keeps the generated voice quiet for a while, e.g. while a hand-recorded clip covers the same lines.</summary>
        public static void SuppressFor(float seconds)
        {
            _suppressUntil = Mathf.Max(_suppressUntil, Time.unscaledTime + seconds);
            Stop();
        }

        private static void EnsureSource()
        {
            if (_source != null) return;
            var go = new GameObject("[DialogueVoice]");
            Object.DontDestroyOnLoad(go);
            _source = go.AddComponent<AudioSource>();
            _source.playOnAwake = false;
            _source.loop = false;
            _source.spatialBlend = 0f;
            _source.priority = 0;
            _source.bypassReverbZones = true;
        }

        // ── Missing-line report (editor only) ───────────────────────────────────

        private static void ReportMissing(string speaker, string text, string key)
        {
#if UNITY_EDITOR
            if (Reported.Count >= 400 || !Reported.Add(key)) return;
            try
            {
                string dir = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Application.dataPath), "VoiceLines");
                System.IO.Directory.CreateDirectory(dir);
                string clean = Tags.Replace(text ?? "", "").Replace("\t", " ").Replace("\r", " ").Replace("\n", " ");
                System.IO.File.AppendAllText(System.IO.Path.Combine(dir, "missing.tsv"), (speaker ?? "") + "\t" + clean + "\n");
            }
            catch { /* reporting must never break the game */ }
#endif
        }
    }
}
